 for(const v of [...model.rivals,...model.police]){let[x,y]=map(v);const dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy);if(d>r-7){x=cx+dx*(r-7)/d;y=cy+dy*(r-7)/d;}const police=v.id.startsWith('patrol');ctx.fillStyle=police?(v.active?'#51baff':'#7696a4'):'#f4e2ba';ctx.beginPath();ctx.arc(x,y,d>r?2:3.3,0,Math.PI*2);ctx.fill();}
